import{_ as t,o,c as a,ae as i}from"./chunks/framework.sRTLHEzD.js";const s="/heidrun_code/screenshots/features/needs_you.png",f=JSON.parse('{"title":"The Needs you sidebar section","description":"Heidrun Code shows one card for each coding agent that is blocked, asks a question, or has finished, so that you know which one needs you.","frontmatter":{"description":"Heidrun Code shows one card for each coding agent that is blocked, asks a question, or has finished, so that you know which one needs you."},"headers":[],"relativePath":"features/needs_you.md","filePath":"features/needs_you.md"}'),n={name:"features/needs_you.md"};function h(d,e,r,c,l,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="the-needs-you-sidebar-section" tabindex="-1">The Needs you sidebar section <a class="header-anchor" href="#the-needs-you-sidebar-section" aria-label="Permalink to &quot;The Needs you sidebar section&quot;">​</a></h1><p>You run several coding agents at the same time. Each coding agent stops from time to time: it asks for a permission, it asks a question, or it has finished and waits for your review. Without help, you find these coding agents only when you look at their terminals one by one.</p><h2 id="what-heidrun-code-does" tabindex="-1">What Heidrun Code does <a class="header-anchor" href="#what-heidrun-code-does" aria-label="Permalink to &quot;What Heidrun Code does&quot;">​</a></h2><p>The Needs you sidebar section, in the right sidebar, holds one card for each coding agent that needs you:</p><ul><li>A coding agent that is blocked: it waits for a decision, for example the permission to run a command.</li><li>A coding agent that asks a question.</li><li>A coding agent that has finished.</li></ul><p>The blocked coding agents come first. The button of the Needs you sidebar section shows the number of cards, and the number turns red when a coding agent is blocked.</p><p><img src="'+s+'" alt="The Needs you sidebar section with the card of a blocked coding agent that asks which title to choose, and under it the list of the two workspaces with their Git branch." width="300"></p><h2 id="what-you-do-with-a-card" tabindex="-1">What you do with a card <a class="header-anchor" href="#what-you-do-with-a-card" aria-label="Permalink to &quot;What you do with a card&quot;">​</a></h2><ul><li>Click the card to go to the pane of the coding agent.</li><li>Answer a blocked coding agent from its card, without going to its pane.</li><li>Pin the pane of the coding agent, so that the pane stays visible.</li><li>Hide the card. A hidden card comes back at the next change of the coding agent.</li></ul><p>A finished coding agent leaves the Needs you sidebar section after a delay that you set in the Settings window.</p><h2 id="the-list-of-workspaces" tabindex="-1">The list of workspaces <a class="header-anchor" href="#the-list-of-workspaces" aria-label="Permalink to &quot;The list of workspaces&quot;">​</a></h2><p>Under the cards, the Needs you sidebar section lists all your workspaces. Each row shows a status dot with the color of the coding agents of the workspace, the name of the workspace, and its Git branch.</p><ul><li>Click a row to go to the workspace.</li><li>Drag a row to change the order of the workspaces.</li><li>Switch off &quot;Show the workspaces&quot; in the section &quot;Needs you&quot; of the Settings window to hide the list.</li></ul><h2 id="even-when-the-window-is-hidden" tabindex="-1">Even when the window is hidden <a class="header-anchor" href="#even-when-the-window-is-hidden" aria-label="Permalink to &quot;Even when the window is hidden&quot;">​</a></h2><p>The status item in the macOS menu bar shows the same states: blocked, finished, and working. Click the status item to see the coding agents of each state, or to open Heidrun Code.</p><p><em>In Valhalla, nobody waits in line for mead. In Heidrun Code, no coding agent waits in a terminal that you forgot.</em></p>',16)])])}const g=t(n,[["render",h]]);export{f as __pageData,g as default};
